def lbs(arr):
    n = len(arr)
    # Initialize the length of the increasing subsequence at each index
    inc_len = [1] * n
    # Initialize the length of the decreasing subsequence at each index
    dec_len = [1] * n

    # Compute the length of the increasing subsequence ending at each element
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc_len[i] = max(inc_len[i], inc_len[j] + 1)

    # Compute the length of the decreasing subsequence starting from each element
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec_len[i] = max(dec_len[i], dec_len[j] + 1)

    # The length of the longest bitonic subsequence is the maximum sum of the increasing and decreasing subsequences
    return max([inc_len[i] + dec_len[i] - 1 for i in range(n)])
```

